@startuml

class Well {
  + code : string
  + pollutionRate() : float
}

class OnshoreWell extends Well {
  + surfaceExtension : float
}

class OffshoreWell extends Well {
  + installationYear : int
  + area : Area
  + pollutionRate() : float
}

class Area {
  + code : string
  + environmentalImportance : int
}

class Company {
  + taxCode : string
  + numberOfEmployees : int
}

class Extraction {
  + quantity : float
}

Well "0..*" -- "0..*" Company : extraction
(Well, Company) .. Extraction

@enduml

